#!/usr/bin/env bash
# Run idf.py without sourcing export.sh or invoking pip/install.sh.
set -euo pipefail

rover_root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
export IDF_PATH="$rover_root/.esp-idf"
export IDF_TOOLS_PATH="$rover_root/.espressif"
export IDF_PYTHON_ENV_PATH="$rover_root/.idf-python"
export UV_PROJECT_ENVIRONMENT="$IDF_PYTHON_ENV_PATH"

if [[ ! -x "$IDF_PYTHON_ENV_PATH/bin/python" || ! -f "$IDF_PATH/tools/idf.py" ]]; then
    printf 'Run tools/setup-idf.sh first.\n' >&2
    exit 1
fi
# Environment statements are generated by the pinned, local official SDK.
idf_exports="$(uv run --project "$rover_root/tools/idf-python" --no-sync \
    "$IDF_PATH/tools/idf_tools.py" export --format shell)"
eval "$idf_exports"
exec uv run --project "$rover_root/tools/idf-python" --no-sync \
    "$IDF_PATH/tools/idf.py" "$@"
